function(container, apiUrl, tables) {
  // テーブルインデックス: エラーログテーブルを想定
  const errorLogTableIdx = 0;
  const validationResultTableIdx = 1;

  let allErrorLogs = [];
  let selectedErrorId = null;

  // ===== 1. 再描画関数 =====
  function renderErrorLogs(logs) {
    const tbody = container.querySelector("#error-tbody");
    if (!logs || logs.length === 0) {
      tbody.innerHTML = '<tr style="height:40px;"><td colspan="7" style="text-align:center; color:var(--text-muted); padding:20px;">エラーがありません</td></tr>';
      return;
    }

    tbody.innerHTML = logs.map(log => {
      const severityColor = log.重要度 === 'CRITICAL' ? '#ff4444' : 
                           log.重要度 === 'ERROR' ? '#ff9900' : 
                           log.重要度 === 'WARNING' ? '#ffcc00' : '#4488ff';
      const statusBg = log.ステータス === '未対応' ? 'rgba(255,68,68,0.15)' :
                       log.ステータス === '対応中' ? 'rgba(255,153,0,0.15)' :
                       log.ステータス === '解決済み' ? 'rgba(68,204,68,0.15)' : 'rgba(100,100,100,0.15)';

      return `<tr data-id="${log.id || log.エラーログID}" style="border-bottom:1px solid rgba(255,255,255,0.05); cursor:pointer; transition:background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background='transparent'">
        <td style="padding:8px; color:var(--text-muted); font-size:11px;">${(log.受注データID || log.id || '').substring(0, 8)}</td>
        <td style="padding:8px; color:var(--text);">${log.受注番号 || '-'}</td>
        <td style="padding:8px; color:var(--text); font-family:monospace;">${log.エラーコード || '-'}</td>
        <td style="padding:8px; color:var(--text); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:200px;">${log.エラーメッセージ || '-'}</td>
        <td style="padding:8px; text-align:center; color:${severityColor}; font-weight:600;">${log.重要度 || '-'}</td>
        <td style="padding:8px; text-align:center; background:${statusBg}; border-radius:3px; color:var(--text); font-size:11px;">${log.ステータス || '-'}</td>
        <td style="padding:8px; color:var(--text-muted); font-size:11px;">${log.作成日時 ? log.作成日時.substring(0, 10) : '-'}</td>
      </tr>`;
    }).join("");

    // 行クリックイベント
    tbody.querySelectorAll("tr").forEach(row => {
      row.addEventListener("click", () => {
        const id = row.dataset.id;
        const log = logs.find(l => (l.id || l.エラーログID) === id);
        if (log) {
          selectedErrorId = id;
          showDetailPanel(log);
        }
      });
    });
  }

  // ===== 2. 詳細パネル表示 =====
  function showDetailPanel(log) {
    const detailPanel = container.querySelector("#detail-panel");
    const noSelection = container.querySelector("#no-selection");

    container.querySelector("#detail-error-id").textContent = log.id || log.エラーログID || '-';
    container.querySelector("#detail-error-msg").textContent = log.エラーメッセージ || '-';
    container.querySelector("#detail-error-detail").textContent = log.エラー詳細 || log.エラー詳細情報 || '-';
    container.querySelector("#detail-error-category").value = log.エラー分類 || '';
    container.querySelector("#detail-assignee").value = log.対応者ID || '';
    container.querySelector("#detail-status").value = log.ステータス || '未対応';
    container.querySelector("#detail-comment").value = log.対応コメント || '';

    detailPanel.style.display = 'block';
    noSelection.style.display = 'none';

    // ログ表示
    const logContainer = container.querySelector("#log-container");
    logContainer.innerHTML = `
      <div style="font-size:11px; line-height:1.6; color:var(--text-muted);">
        <div><strong>エラーコード:</strong> ${log.エラーコード || '-'}</div>
        <div><strong>エラー種別:</strong> ${log.エラー種別 || '-'}</div>
        <div><strong>発生モジュール:</strong> ${log.発生モジュール || '-'}</div>
        <div><strong>重要度:</strong> ${log.重要度 || '-'}</div>
        <div><strong>作成日時:</strong> ${log.作成日時 || '-'}</div>
        <div><strong>再処理可能:</strong> ${log.再処理可能フラグ ? 'はい' : 'いいえ'}</div>
      </div>
    `;
  }

  // ===== 3. KPI 更新 =====
  function updateKPIs(logs) {
    const today = new Date().toISOString().split('T')[0];
    const todayLogs = logs.filter(l => (l.作成日時 || '').startsWith(today));
    const criticalCount = logs.filter(l => l.重要度 === 'CRITICAL').length;
    const pendingCount = logs.filter(l => l.ステータス === '未対応').length;

    // 連携成功率（基幹システム連携履歴から推測）
    const successRate = tables[1] && tables[1].records ? 
      Math.round((tables[1].records.filter(r => r.処理ステータス === '成功').length / tables[1].records.length) * 100) : 0;

    container.querySelector("[data-testid='kpi-today-errors']").textContent = todayLogs.length;
    container.querySelector("[data-testid='kpi-critical-errors']").textContent = criticalCount;
    container.querySelector("[data-testid='kpi-pending-errors']").textContent = pendingCount;
    container.querySelector("[data-testid='kpi-success-rate']").textContent = successRate + '%';
  }

  // ===== 4. フィルタ適用 =====
  function applyFilters() {
    const orderNo = container.querySelector("#filter-order-no").value.toLowerCase();
    const severity = container.querySelector("#filter-severity").value;
    const status = container.querySelector("#filter-status").value;
    const dateFrom = container.querySelector("#filter-date-from").value;

    let filtered = allErrorLogs;

    if (orderNo) filtered = filtered.filter(l => (l.受注番号 || '').toLowerCase().includes(orderNo));
    if (severity) filtered = filtered.filter(l => l.重要度 === severity);
    if (status) filtered = filtered.filter(l => l.ステータス === status);
    if (dateFrom) filtered = filtered.filter(l => (l.作成日時 || '').startsWith(dateFrom));

    renderErrorLogs(filtered);
  }

  // ===== 5. 初期データ読み込み =====
  async function loadInitialData() {
    try {
      const logs = await window.aivicApi.list(errorLogTableIdx);
      if (logs && logs.length > 0) {
        allErrorLogs = logs;
        renderErrorLogs(logs);
        updateKPIs(logs);
      }
    } catch (err) {
      console.error("Failed to load error logs:", err);
    }
  }

  // ===== 6. イベントリスナー登録 =====

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  // バリデーション実行ボタン
  container.querySelector("#btn-validate").addEventListener("click", async () => {
    alert("バリデーション実行処理を開始します...");
    // 実装: バリデーション実行 API 呼び出し
    loadInitialData();
  });

  // エラー更新ボタン
  container.querySelector("#btn-update-error").addEventListener("click", async () => {
    if (!selectedErrorId) return;

    const category = container.querySelector("#detail-error-category").value;
    const assignee = container.querySelector("#detail-assignee").value;
    const status = container.querySelector("#detail-status").value;
    const comment = container.querySelector("#detail-comment").value;

    try {
      await window.aivicApi.update(errorLogTableIdx, selectedErrorId, {
        エラー分類: category,
        対応者ID: assignee,
        ステータス: status,
        対応コメント: comment
      });
      alert("エラー情報を更新しました");
      loadInitialData();
    } catch (err) {
      console.error("Failed to update error:", err);
    }
  });

  // 通知送信ボタン
  container.querySelector("#btn-send-notification").addEventListener("click", async () => {
    if (!selectedErrorId) return;
    const assignee = container.querySelector("#detail-assignee").value;
    if (!assignee) {
      alert("責任者を選択してください");
      return;
    }
    alert(`責任者 ${assignee} に通知を送信しました`);
    // 実装: 通知送信 API 呼び出し
  });

  // バリデーションルール確認リンク
  container.querySelector("#link-validation-rules").addEventListener("click", (e) => {
    e.preventDefault();
    window.showScreen("scr-1781408640983");
  });

  // 基幹システム連携履歴リンク
  container.querySelector("#link-integration-history").addEventListener("click", (e) => {
    e.preventDefault();
    window.showScreen("scr-1781408509581");
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス（tables 配列内の位置）
  const TABLE_INTEGRATION_HISTORY = 0;  // 基幹システム連携履歴
  const TABLE_VALIDATION_RESULT = 1;    // バリデーション結果
  const TABLE_ERROR_LOG = 2;            // エラーログ
  const TABLE_ERROR_CLASSIFICATION = 3; // エラー分類マスタ
  const TABLE_APPROVED_ORDERS = 4;      // 承認済み受注
  const TABLE_MONTHLY_VARIANCE = 5;     // 月次差異検証
  const TABLE_LOGIN_USER = 6;           // ログインユーザー
  const TABLE_USER_PERMISSION = 7;      // ユーザー権限
  const TABLE_INTEGRATION_REFLECTION = 8; // 連携反映状況

  // ============================================
  // 1. ユーザー情報・権限表示
  // ============================================
  function displayUserInfo() {
    const users = tables[TABLE_LOGIN_USER]?.records || [];
    const permissions = tables[TABLE_USER_PERMISSION]?.records || [];

    // 最初のユーザーを表示（実装では認証情報から取得）
    const currentUser = users[0];
    if (currentUser) {
      container.querySelector("#user-name").textContent = currentUser.ユーザー名 || "-";
      container.querySelector("#user-role").textContent = currentUser.ロール || "-";

      const userPerms = permissions.filter(p => p.ユーザーID === currentUser.ユーザーID);
      const permList = [];
      if (userPerms.some(p => p.データ検証実行権限)) permList.push("検証実行");
      if (userPerms.some(p => p.承認権限)) permList.push("承認");
      if (userPerms.some(p => p.ユーザー管理権限)) permList.push("管理");
      container.querySelector("#user-permissions").textContent = permList.length > 0 ? permList.join(" / ") : "閲覧のみ";
    }
  }

  // ============================================
  // 2. 連携実行ステータス一覧の再描画
  // ============================================
  function renderIntegrationStatus(rows) {
    const tbody = container.querySelector("#integration-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="5" style="padding: 12px; text-align: center; color: var(--text-muted);">データなし</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(row => {
      const statusColor = row.処理ステータス === "成功" ? "#4ade80" : 
                         row.処理ステータス === "失敗" ? "#ef4444" : 
                         row.処理ステータス === "実行中" ? "#f97316" : "#9fb0d1";
      const successRate = row.送信データ件数 > 0 ? Math.round((row.成功件数 / row.送信データ件数) * 100) : 0;

      return `
        <tr data-id="${row.連携履歴ID}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 8px; color: var(--text);">${new Date(row.実行開始日時).toLocaleString('ja-JP', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' })}</td>
          <td style="padding: 8px; color: var(--text);">-</td>
          <td style="padding: 8px; color: var(--text);">-</td>
          <td style="padding: 8px; text-align: center; color: ${statusColor}; font-weight: 600;">${row.処理ステータス}</td>
          <td style="padding: 8px; text-align: center; color: var(--text-muted); font-size: 11px;">${row.成功件数}/${row.送信データ件数} (${successRate}%)</td>
        </tr>
      `;
    }).join("");
  }

  // ============================================
  // 3. KPI カード更新
  // ============================================
  function updateKPIs() {
    const integrations = tables[TABLE_INTEGRATION_HISTORY]?.records || [];
    const errors = tables[TABLE_ERROR_LOG]?.records || [];

    const today = new Date().toDateString();
    const todayIntegrations = integrations.filter(i => new Date(i.実行開始日時).toDateString() === today);
    const successCount = todayIntegrations.filter(i => i.処理ステータス === "成功").length;
    const failureCount = todayIntegrations.filter(i => i.処理ステータス === "失敗").length;
    const pendingErrors = errors.filter(e => e.ステータス === "未対応").length;

    container.querySelector("[data-testid='kpi-today-executions']").textContent = todayIntegrations.length;
    container.querySelector("[data-testid='kpi-success-count']").textContent = successCount;
    container.querySelector("[data-testid='kpi-failure-count']").textContent = failureCount;
    container.querySelector("[data-testid='kpi-pending-errors']").textContent = pendingErrors;
  }

  // ============================================
  // 4. エラー分類別集計
  // ============================================
  function updateErrorClassification() {
    const errors = tables[TABLE_ERROR_LOG]?.records || [];
    const classifications = tables[TABLE_ERROR_CLASSIFICATION]?.records || [];

    const errorCounts = {};
    errors.forEach(e => {
      const cls = classifications.find(c => c.エラー分類ID === e.エラー分類ID);
      const name = cls ? cls.エラー分類名 : "不明";
      errorCounts[name] = (errorCounts[name] || 0) + 1;
    });

    const container_el = container.querySelector("#error-classification");
    if (Object.keys(errorCounts).length === 0) {
      container_el.innerHTML = '<div style="color: var(--text-muted);">エラーなし</div>';
    } else {
      container_el.innerHTML = Object.entries(errorCounts)
        .sort((a, b) => b[1] - a[1])
        .map(([name, count]) => `
          <div style="display: flex; justify-content: space-between; padding: 4px 0; border-bottom: 1px solid rgba(255,255,255,0.05);">
            <span style="color: var(--text);">${name}</span>
            <span style="color: #ef4444; font-weight: 600;">${count}</span>
          </div>
        `).join("");
    }
  }

  // ============================================
  // 5. 承認済み受注一覧
  // ============================================
  function updateApprovedOrders() {
    const approved = tables[TABLE_APPROVED_ORDERS]?.records || [];
    const container_el = container.querySelector("#approved-orders");

    if (approved.length === 0) {
      container_el.innerHTML = '<div style="color: var(--text-muted);">承認済み受注なし</div>';
    } else {
      container_el.innerHTML = approved.slice(0, 5).map(order => `
        <div style="padding: 4px; background: rgba(74, 222, 128, 0.1); border-radius: 2px; border-left: 2px solid #4ade80;">
          <div style="color: var(--text); font-weight: 500;">受注ID: ${order.受注ID?.substring(0, 8) || "-"}</div>
          <div style="color: var(--text-muted); font-size: 10px;">承認: ${new Date(order.承認日時).toLocaleDateString('ja-JP')}</div>
        </div>
      `).join("");
    }
  }

  // ============================================
  // 6. 月次差異検証結果
  // ============================================
  function updateMonthlyVariance() {
    const variances = tables[TABLE_MONTHLY_VARIANCE]?.records || [];
    const container_el = container.querySelector("#monthly-variance");

    const unresolved = variances.filter(v => v.検証ステータス !== "解決済");
    if (unresolved.length === 0) {
      container_el.innerHTML = '<div style="color: #4ade80; font-weight: 500;">差異なし</div>';
    } else {
      container_el.innerHTML = unresolved.slice(0, 3).map(v => `
        <div style="padding: 4px; background: rgba(249, 115, 22, 0.1); border-radius: 2px; border-left: 2px solid #f97316;">
          <div style="color: var(--text); font-size: 11px;">${v.差異タイプ}</div>
          <div style="color: var(--text-muted); font-size: 10px;">金額: ¥${v.差異金額?.toLocaleString() || "0"}</div>
        </div>
      `).join("");
    }
  }

  // ============================================
  // 7. 連携反映状況タイムライン
  // ============================================
  function updateTimeline() {
    const reflections = tables[TABLE_INTEGRATION_REFLECTION]?.records || [];
    const container_el = container.querySelector("#timeline-container");

    if (reflections.length === 0) {
      container_el.innerHTML = '<div style="font-size: 11px; color: var(--text-muted); text-align: center;">イベントなし</div>';
    } else {
      container_el.innerHTML = reflections.slice(0, 6).map(r => {
        const statusColor = r.反映ステータス === "成功" ? "#4ade80" : 
                           r.反映ステータス === "失敗" ? "#ef4444" : "#f97316";
        return `
          <div style="display: flex; gap: 6px; padding: 6px; border-left: 2px solid ${statusColor}; background: rgba(0,0,0,0.15); border-radius: 2px;">
            <div style="flex-shrink: 0; width: 6px; height: 6px; border-radius: 50%; background: ${statusColor}; margin-top: 4px;"></div>
            <div style="flex: 1;">
              <div style="color: var(--text); font-size: 11px; font-weight: 500;">${r.反映ステータス}</div>
              <div style="color: var(--text-muted); font-size: 10px;">${new Date(r.反映開始日時).toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' })}</div>
              <div style="color: var(--text-muted); font-size: 10px;">成功: ${r.反映成功件数}/${r.受信件数}</div>
            </div>
          </div>
        `;
      }).join("");
    }
  }

  // ============================================
  // 8. 検索機能
  // ============================================
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#search-keyword").value.toLowerCase();
    const status = container.querySelector("#filter-status").value;

    const integrations = await window.aivicApi.list(TABLE_INTEGRATION_HISTORY) || tables[TABLE_INTEGRATION_HISTORY]?.records || [];

    const filtered = integrations.filter(row => {
      const matchKeyword = !keyword || JSON.stringify(row).toLowerCase().includes(keyword);
      const matchStatus = !status || row.処理ステータス === status;
      return matchKeyword && matchStatus;
    });

    renderIntegrationStatus(filtered);
  });

  // ============================================
  // 9. 連携実行ボタン
  // ============================================
  container.querySelector("#btn-execute-integration").addEventListener("click", async () => {
    if (!confirm("基幹システムへの連携を実行しますか？")) return;

    // 連携実行処理（実装例）
    const newIntegration = {
      連携種別: "受注同期",
      連携方向: "送信",
      処理ステータス: "実行中",
      送信データ件数: 0,
      成功件数: 0,
      失敗件数: 0,
      実行開始日時: new Date().toISOString(),
      実行トリガー: "手動"
    };

    const saved = await window.aivicApi.save(TABLE_INTEGRATION_HISTORY, newIntegration);
    if (saved) {
      alert("連携実行を開始しました");
      const updated = await window.aivicApi.list(TABLE_INTEGRATION_HISTORY);
      if (updated) {
        renderIntegrationStatus(updated);
        updateKPIs();
        updateTimeline();
      }
    }
  });

  // ============================================
  // 10. 失敗分再実行ボタン
  // ============================================
  container.querySelector("#btn-retry-failed").addEventListener("click", async () => {
    const integrations = await window.aivicApi.list(TABLE_INTEGRATION_HISTORY) || tables[TABLE_INTEGRATION_HISTORY]?.records || [];
    const failedCount = integrations.filter(i => i.処理ステータス === "失敗").length;

    if (failedCount === 0) {
      alert("失敗した連携はありません");
      return;
    }

    if (!confirm(`失敗した ${failedCount} 件の連携を再実行しますか？`)) return;

    alert("失敗分の再実行を開始しました");
    updateKPIs();
  });

  // ============================================
  // 11. 詳細ログボタン
  // ============================================
  container.querySelector("#btn-detail-log").addEventListener("click", () => {
    window.showScreen("scr-1781408467707");
  });

  // ============================================
  // 12. 行クリックでエラー詳細表示
  // ============================================
  container.addEventListener("click", async (e) => {
    const row = e.target.closest("tr[data-id]");
    if (!row) return;

    const integrationId = row.dataset.id;
    const integrations = tables[TABLE_INTEGRATION_HISTORY]?.records || [];
    const integration = integrations.find(i => i.連携履歴ID === integrationId);

    if (integration && integration.処理ステータス === "失敗") {
      const errorPanel = container.querySelector("#error-detail-panel");
      const errorContent = container.querySelector("#error-detail-content");
      errorContent.textContent = integration.エラー詳細 || "エラー詳細情報なし";
      errorPanel.style.display = "block";
    }
  });

  // ============================================
  // 13. 初期化：ユーザー情報表示 + 全データ描画
  // ============================================
  displayUserInfo();
  renderIntegrationStatus(tables[TABLE_INTEGRATION_HISTORY]?.records || []);
  updateKPIs();
  updateErrorClassification();
  updateApprovedOrders();
  updateMonthlyVariance();
  updateTimeline();
}

function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const connHistoryIdx = tables.findIndex(t => t.tableName === '基幹システム連携履歴');
  const connStatusIdx = tables.findIndex(t => t.tableName === '連携反映状況');
  const errorLogIdx = tables.findIndex(t => t.tableName === 'エラーログ');
  const errorClassIdx = tables.findIndex(t => t.tableName === 'エラー分類マスタ');

  const timelineContainer = container.querySelector('#timeline-container');
  const errorDetailPanel = container.querySelector('#error-detail-panel');
  const errorDetailContent = container.querySelector('#error-detail-content');
  const kpiTotalCount = container.querySelector('[data-testid="kpi-total-count"]');
  const kpiSuccessCount = container.querySelector('[data-testid="kpi-success-count"]');
  const kpiErrorCount = container.querySelector('[data-testid="kpi-error-count"]');
  const kpiWarningCount = container.querySelector('[data-testid="kpi-warning-count"]');

  const filterDateFrom = container.querySelector('[data-testid="filter-date-from"]');
  const filterStatus = container.querySelector('[data-testid="filter-status"]');
  const filterErrorType = container.querySelector('[data-testid="filter-error-type"]');
  const searchOrderId = container.querySelector('[data-testid="search-order-id"]');
  const filterResponsible = container.querySelector('[data-testid="filter-responsible"]');
  const filterResponseStatus = container.querySelector('[data-testid="filter-response-status"]');
  const refreshBtn = container.querySelector('[data-testid="refresh-button"]');
  const exportBtn = container.querySelector('[data-testid="export-button"]');

  let allConnHistory = [];
  let allConnStatus = [];
  let allErrorLogs = [];
  let selectedItem = null;

  // 1. 初期データ読み込み
  async function loadData() {
    if (connHistoryIdx >= 0) {
      allConnHistory = tables[connHistoryIdx].records || [];
    }
    if (connStatusIdx >= 0) {
      allConnStatus = tables[connStatusIdx].records || [];
    }
    if (errorLogIdx >= 0) {
      allErrorLogs = tables[errorLogIdx].records || [];
    }
    renderTimeline(allConnHistory);
    updateKPI();
  }

  // 2. KPI 更新
  function updateKPI() {
    const total = allConnHistory.length;
    const success = allConnHistory.filter(h => h.処理ステータス === '成功').length;
    const error = allConnHistory.filter(h => h.処理ステータス === '失敗').length;
    const warning = allConnHistory.filter(h => h.処理ステータス === '部分成功').length;

    kpiTotalCount.textContent = total;
    kpiSuccessCount.textContent = success;
    kpiErrorCount.textContent = error;
    kpiWarningCount.textContent = warning;
  }

  // 3. タイムラインレンダリング
  function renderTimeline(items) {
    timelineContainer.innerHTML = items.map(item => {
      const statusClass = getStatusClass(item.処理ステータス);
      const timestamp = new Date(item.実行開始日時).toLocaleString('ja-JP');
      const errorCount = item.失敗件数 || 0;
      const successCount = item.成功件数 || 0;

      return `
        <div class="timeline-item ${statusClass}" data-id="${item.連携履歴ID}" style="cursor: pointer;">
          <div class="timeline-item-body">
            <div class="timeline-item-header">
              <div style="font-weight: 600; color: var(--text);">${item.連携種別 || '連携処理'}</div>
              <span class="timeline-item-status ${statusClass}">${item.処理ステータス}</span>
            </div>
            <div class="timeline-item-meta">
              <span>${timestamp}</span>
              <span>成功: ${successCount} / 失敗: ${errorCount}</span>
            </div>
            <div style="font-size: 11px; color: var(--text-muted);">
              ${item.エラー詳細 ? item.エラー詳細.substring(0, 60) + '...' : '処理完了'}
            </div>
          </div>
        </div>
      `;
    }).join('');

    // イベントデリゲーション: タイムラインアイテムクリック
    timelineContainer.addEventListener('click', e => {
      const item = e.target.closest('.timeline-item');
      if (item) {
        const id = item.dataset.id;
        selectedItem = allConnHistory.find(h => h.連携履歴ID === id);
        showErrorDetail(selectedItem);
      }
    });
  }

  // 4. ステータスクラス判定
  function getStatusClass(status) {
    if (status === '成功') return 'success';
    if (status === '失敗') return 'error';
    if (status === '部分成功') return 'partial';
    if (status === '警告') return 'warning';
    return 'partial';
  }

  // 5. エラー詳細表示
  function showErrorDetail(item) {
    if (!item) {
      errorDetailContent.innerHTML = 'アイテムを選択してください';
      return;
    }

    const relatedErrors = allErrorLogs.filter(e => e.バリデーション結果ID === item.連携履歴ID);
    const errorHtml = `
      <div style="display: flex; flex-direction: column; gap: 8px;">
        <div>
          <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 2px;">連携種別</div>
          <div style="font-size: 12px; color: var(--text); font-weight: 500;">${item.連携種別 || 'N/A'}</div>
        </div>
        <div>
          <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 2px;">ステータス</div>
          <div style="font-size: 12px; color: var(--text); font-weight: 500;">${item.処理ステータス}</div>
        </div>
        <div>
          <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 2px;">実行日時</div>
          <div style="font-size: 12px; color: var(--text);">${new Date(item.実行開始日時).toLocaleString('ja-JP')}</div>
        </div>
        <div>
          <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 2px;">成功件数</div>
          <div style="font-size: 12px; color: #4ade80; font-weight: 600;">${item.成功件数 || 0}</div>
        </div>
        <div>
          <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 2px;">失敗件数</div>
          <div style="font-size: 12px; color: #ef4444; font-weight: 600;">${item.失敗件数 || 0}</div>
        </div>
        ${item.エラー詳細 ? `
          <div style="border-top: 1px solid var(--border); padding-top: 8px; margin-top: 8px;">
            <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 4px;">エラーメッセージ</div>
            <div style="font-size: 11px; color: #ef4444; word-break: break-word; max-height: 100px; overflow-y: auto; background: rgba(239,68,68,0.1); padding: 6px; border-radius: 2px;">
              ${item.エラー詳細}
            </div>
          </div>
        ` : ''}
        ${relatedErrors.length > 0 ? `
          <div style="border-top: 1px solid var(--border); padding-top: 8px; margin-top: 8px;">
            <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 4px;">関連エラー (${relatedErrors.length}件)</div>
            <div style="font-size: 11px; color: var(--text); max-height: 80px; overflow-y: auto;">
              ${relatedErrors.map(e => `<div style="margin-bottom: 4px; padding: 4px; background: rgba(0,0,0,0.2); border-radius: 2px;">
                <strong>${e.エラーコード}</strong>: ${e.エラーメッセージ ? e.エラーメッセージ.substring(0, 40) + '...' : 'N/A'}
              </div>`).join('')}
            </div>
          </div>
        ` : ''}
      </div>
    `;
    errorDetailContent.innerHTML = errorHtml;
  }

  // 6. フィルター適用
  function applyFilters() {
    let filtered = [...allConnHistory];

    const dateFrom = filterDateFrom.value;
    if (dateFrom) {
      filtered = filtered.filter(h => new Date(h.実行開始日時).toISOString().split('T')[0] >= dateFrom);
    }

    const status = filterStatus.value;
    if (status) {
      filtered = filtered.filter(h => h.処理ステータス === status);
    }

    const errorType = filterErrorType.value;
    if (errorType) {
      filtered = filtered.filter(h => {
        const relatedErrors = allErrorLogs.filter(e => e.バリデーション結果ID === h.連携履歴ID);
        return relatedErrors.some(e => e.エラー種別 === errorType);
      });
    }

    const orderId = searchOrderId.value.trim();
    if (orderId) {
      filtered = filtered.filter(h => h.連携履歴ID.includes(orderId) || (h.エラー詳細 && h.エラー詳細.includes(orderId)));
    }

    renderTimeline(filtered);
    updateKPI();
  }

  // 7. イベントリスナー登録
  filterDateFrom.addEventListener('change', applyFilters);
  filterStatus.addEventListener('change', applyFilters);
  filterErrorType.addEventListener('change', applyFilters);
  searchOrderId.addEventListener('input', applyFilters);
  filterResponsible.addEventListener('change', applyFilters);
  filterResponseStatus.addEventListener('change', applyFilters);

  // 8. 更新ボタン
  refreshBtn.addEventListener('click', async () => {
    if (connHistoryIdx >= 0) {
      const data = await window.aivicApi.list(connHistoryIdx);
      if (data) {
        allConnHistory = data;
        renderTimeline(allConnHistory);
        updateKPI();
      }
    }
  });

  // 9. CSVエクスポート
  exportBtn.addEventListener('click', () => {
    if (allConnHistory.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['連携履歴ID', '連携種別', '連携方向', '処理ステータス', '送信データ件数', '成功件数', '失敗件数', '実行開始日時', '実行終了日時', 'エラー詳細'];
    const rows = allConnHistory.map(h => [
      h.連携履歴ID || '',
      h.連携種別 || '',
      h.連携方向 || '',
      h.処理ステータス || '',
      h.送信データ件数 || '',
      h.成功件数 || '',
      h.失敗件数 || '',
      h.実行開始日時 || '',
      h.実行終了日時 || '',
      h.エラー詳細 ? h.エラー詳細.replace(/"/g, '""') : ''
    ]);

    const csv = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(cell => `"${cell}"`).join(',')
    ).join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `連携結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 初期化
  loadData();
}

