function(container, apiUrl, tables) {
  // テーブルインデックスの特定
  const validationResultIdx = tables.findIndex(t => t.tableName === 'バリデーション結果') || 0;
  const errorLogIdx = tables.findIndex(t => t.tableName === 'エラーログ') || 1;
  const testHistoryIdx = tables.findIndex(t => t.tableName === 'テスト実行履歴') || 2;

  // 1. テスト実行履歴タイムラインの再描画
  function renderTestHistory(records) {
    const timeline = container.querySelector('#test-history-timeline');
    if (!records || records.length === 0) {
      timeline.innerHTML = '<p style="font-size: 12px; color: var(--text-muted);">実行履歴がありません</p>';
      return;
    }
    timeline.innerHTML = records.slice(0, 10).map(r => {
      const statusColor = r.検証ステータス === '成功' ? '#4ade80' : r.検証ステータス === '失敗' ? '#ef4444' : '#f59e0b';
      return `
        <div data-id="${r.id || r.バリデーション結果ID}" style="border-left: 3px solid ${statusColor}; padding: 8px; background: rgba(0,0,0,0.2); border-radius: 3px; cursor: pointer;" class="timeline-item">
          <div style="font-size: 11px; color: var(--text-muted);">${r.実行日時 || new Date().toISOString().slice(0,19)}</div>
          <div style="font-size: 12px; font-weight: 600; color: var(--text); margin: 2px 0;">${r.検証ステータス || 'N/A'}</div>
          <div style="font-size: 11px; color: var(--text-muted);">ルール: ${r.バリデーションルールID || 'N/A'}</div>
          <div style="font-size: 11px; color: var(--text-muted);">実行者: ${r.実行ユーザーID || 'N/A'}</div>
        </div>
      `;
    }).join('');
  }

  // 2. バリデーション結果の表示
  function displayValidationResult(record) {
    const panel = container.querySelector('#validation-result-panel');
    if (!record) {
      panel.innerHTML = '<p>テストを実行してください</p>';
      return;
    }
    const resultHtml = `
      <div style="margin-bottom: 8px;">
        <strong style="color: var(--text);">ステータス:</strong> <span style="color: ${record.検証ステータス === '成功' ? '#4ade80' : '#ef4444'};">${record.検証ステータス || 'N/A'}</span>
      </div>
      <div style="margin-bottom: 8px;">
        <strong style="color: var(--text);">エラーメッセージ:</strong><br />
        <span>${record.エラーメッセージ || 'なし'}</span>
      </div>
      <div style="margin-bottom: 8px;">
        <strong style="color: var(--text);">エラーフィールド:</strong> ${record.エラーフィールド || 'N/A'}
      </div>
      <div>
        <strong style="color: var(--text);">エラー値:</strong> <code style="background: rgba(0,0,0,0.3); padding: 2px 4px; border-radius: 2px; font-size: 11px;">${record.エラー値 || 'N/A'}</code>
      </div>
    `;
    panel.innerHTML = resultHtml;
  }

  // 3. エラーログプレビューの表示
  function displayErrorLogPreview(records) {
    const preview = container.querySelector('#error-log-preview');
    if (!records || records.length === 0) {
      preview.textContent = 'エラーログはありません';
      return;
    }
    const logText = records.slice(0, 5).map(r => 
      `[${r.重要度 || 'INFO'}] ${r.エラーコード || 'N/A'}: ${r.エラーメッセージ || 'N/A'}`
    ).join('\n');
    preview.textContent = logText;
  }

  // 4. 初期データ読み込み
  async function loadInitialData() {
    const valResults = await window.aivicApi.list(validationResultIdx);
    const errorLogs = await window.aivicApi.list(errorLogIdx);

    renderTestHistory(valResults || tables[validationResultIdx]?.records || []);
    if (valResults && valResults.length > 0) {
      displayValidationResult(valResults[0]);
    }
    displayErrorLogPreview(errorLogs || tables[errorLogIdx]?.records || []);
  }

  loadInitialData();

  // 5. テスト実行ボタン
  container.querySelector('[data-testid="execute-test-button"]').addEventListener('click', async () => {
    const targetSystem = container.querySelector('[data-testid="target-system-select"]').value;
    const testData = container.querySelector('[data-testid="test-data-input"]').value;
    const validationRule = container.querySelector('[data-testid="validation-rule-select"]').value;
    const autoRetry = container.querySelector('[data-testid="auto-retry-check"]').checked;

    if (!targetSystem || !testData || !validationRule) {
      alert('すべての項目を入力してください');
      return;
    }

    try {
      const testDataObj = JSON.parse(testData);
      const newRecord = {
        検証ステータス: '成功',
        エラーメッセージ: null,
        エラーフィールド: null,
        エラー値: null,
        実行日時: new Date().toISOString(),
        実行ユーザーID: 'current-user',
        バリデーションルールID: validationRule,
        再検証フラグ: false
      };
      const saved = await window.aivicApi.save(validationResultIdx, newRecord);
      if (saved) {
        const updated = await window.aivicApi.list(validationResultIdx);
        renderTestHistory(updated);
        displayValidationResult(newRecord);
        alert('テスト実行完了');
      }
    } catch (e) {
      alert('テストデータが無効です: ' + e.message);
    }
  });

  // 6. タイムラインアイテムクリック
  container.addEventListener('click', (e) => {
    const item = e.target.closest('.timeline-item');
    if (item) {
      const id = item.dataset.id;
      window.aivicApi.list(validationResultIdx).then(records => {
        const record = records.find(r => r.id === id || r.バリデーション結果ID === id);
        if (record) displayValidationResult(record);
      });
    }
