  // 7. ログダウンロード
  container.querySelector('[data-testid="download-log-button"]').addEventListener('click', async () => {
    const format = container.querySelector('[data-testid="log-format-select"]').value;
    const errorLogs = await window.aivicApi.list(errorLogIdx);

    if (!errorLogs || errorLogs.length === 0) {
      alert('ダウンロードするログがありません');
      return;
    }

    let content = '';
    let filename = '';

    if (format === 'csv') {
      const headers = ['エラーコード', '重要度', 'エラーメッセージ', '発生日時', 'ステータス'];
      content = '\uFEFF' + headers.join(',') + '\n';
      content += errorLogs.map(r => 
        `"${r.エラーコード || ''}","${r.重要度 || ''}","${(r.エラーメッセージ || '').replace(/"/g, '""')}","${r.作成日時 || ''}","${r.ステータス || ''}"`
      ).join('\n');
      filename = 'error-logs.csv';
    } else if (format === 'json') {
      content = JSON.stringify(errorLogs, null, 2);
      filename = 'error-logs.json';
    } else {
      content = errorLogs.map(r => 
        `[${r.重要度 || 'INFO'}] ${r.エラーコード || 'N/A'}\n${r.エラーメッセージ || 'N/A'}\n詳細: ${r.エラー詳細 || 'N/A'}\n---`
      ).join('\n');
      filename = 'error-logs.txt';
    }

    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
